package br.com.cineo;
import android.graphics.*;import android.graphics.drawable.*;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import static br.com.cineo.MainActivity.*;
/** Private-storage artwork loaded through the authenticated API, with stable disk cache and visible retry. */
class Artwork {
 final MainActivity a;Artwork(MainActivity activity){a=activity;}
 FrameLayout poster(JSONObject show,int height,boolean banner){FrameLayout frame=new FrameLayout(a);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff3a2238,0xff172f40});gradient.setCornerRadius(a.dp(12));frame.setBackground(gradient);frame.setClipToOutline(true);frame.setMinimumHeight(a.dp(height));ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView state=a.label("Carregando capa…",12,MUTED);state.setGravity(Gravity.CENTER);state.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));frame.addView(state,new FrameLayout.LayoutParams(-1,-1));String resource=show.optString(banner?"banner_url":"cover_url");if(resource.isEmpty())resource=show.optString("cover_url");if(resource.startsWith("android.resource://")){a.image(image,resource);state.setVisibility(View.GONE);return frame;}String key=show.optInt("id")+":"+(banner?(show.optString("banner_path").isEmpty()?show.optString("cover_path"):show.optString("banner_path")):show.optString("cover_path"));Runnable load=()->load(show.optInt("id"),banner,key,image,state);state.setOnClickListener(v->load.run());load.run();return frame;}
 void load(int id,boolean banner,String key,ImageView target,TextView state){String tag=id+":"+banner;target.setTag(tag);Bitmap cached=a.cache.get("art:"+key);if(cached!=null){target.setImageBitmap(cached);state.setVisibility(View.GONE);return;}state.setText("Carregando capa…");state.setVisibility(View.VISIBLE);File file=new File(a.getCacheDir(),"art-"+android.util.Base64.encodeToString(key.getBytes(java.nio.charset.StandardCharsets.UTF_8),android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING)+".jpg");a.images.execute(()->{try{Bitmap bitmap=file.isFile()?BitmapFactory.decodeFile(file.getAbsolutePath()):null;if(bitmap==null){JSONObject r=a.request("GET","/v6/art/"+id+"?kind="+(banner?"banner":"cover"),null,a.token);byte[] bytes=android.util.Base64.decode(r.getString("image"),2);bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new IOException("Imagem inválida");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}}final Bitmap result=bitmap;a.cache.put("art:"+key,result);a.runOnUiThread(()->{if(!tag.equals(target.getTag()))return;target.setImageBitmap(result);target.setAlpha(1f);state.setVisibility(View.GONE);});}catch(Exception ex){a.runOnUiThread(()->{if(!tag.equals(target.getTag()))return;state.setText("Capa indisponível\nToque para recarregar");state.setVisibility(View.VISIBLE);});}});}
}
